create table users (id bigint not null auto_increment primary key, name varchar(100) not null, email varchar(190) not null unique, password_hash varchar(255) not null, role varchar(20) not null, approval_status varchar(20) not null, created_at datetime(6) not null) engine=InnoDB;
create table subjects (id bigint not null auto_increment primary key, name varchar(120) not null, code varchar(30) not null unique) engine=InnoDB;
create table announcements (id bigint not null auto_increment primary key, title varchar(180) not null, content text not null, priority varchar(20) not null, subject_id bigint null, created_by bigint not null, created_at datetime(6) not null, updated_at datetime(6) not null, constraint fk_ann_subject foreign key(subject_id) references subjects(id), constraint fk_ann_user foreign key(created_by) references users(id)) engine=InnoDB;
create table calendar_events (id bigint not null auto_increment primary key, title varchar(180) not null, description text, event_type varchar(30) not null, start_at datetime(6) not null, end_at datetime(6) not null, location varchar(180), subject_id bigint null, created_by bigint not null, created_at datetime(6) not null, updated_at datetime(6) not null, constraint fk_evt_subject foreign key(subject_id) references subjects(id), constraint fk_evt_user foreign key(created_by) references users(id)) engine=InnoDB;
create table resources (id bigint not null auto_increment primary key, display_name varchar(255) not null, storage_name varchar(255) not null unique, content_type varchar(150) not null, file_size bigint not null, subject_id bigint not null, uploaded_by bigint not null, uploaded_at datetime(6) not null, constraint fk_res_subject foreign key(subject_id) references subjects(id), constraint fk_res_user foreign key(uploaded_by) references users(id)) engine=InnoDB;
create index idx_events_start on calendar_events(start_at);
create index idx_resources_subject on resources(subject_id);
